export const CLASSES={sword:{name:'Мечник',damage:9.75,cooldown:.65,incoming:.8,regen:1,stamina:1},bow:{name:'Лучник',damage:8.5,cooldown:.9,incoming:1,regen:1,stamina:2},mage:{name:'Маг',damage:14,cooldown:.9,incoming:1.1,regen:.5,stamina:1}};
export const MAX_LEVEL=100;
export function xpRequired(level){const n=Math.max(0,Math.min(99,Math.floor(level)-1));return level>=MAX_LEVEL?0:250+40*n+3*n*n}
export function migrateProgress(p,legacy=false){p.level=Math.max(1,Math.min(MAX_LEVEL,Math.floor(p.level)));if(p.level===MAX_LEVEL)p.xp=0;else if(legacy)p.xp=Math.floor(p.xp/250*xpRequired(p.level));p.pendingLevels=Math.max(0,Math.min(p.level-1,p.pendingLevels||0));p.progressionVersion=2;return p}
export function createProgress(){return {progressionVersion:2,checkpoint:null,lastDeathAt:null,gold:0,stage:'safe',rejected:false,classId:null,xp:0,level:1,arrows:0,rewards:[],wolfDead:false,pendingLevels:0}}
export const QUEST_GOLD={safe:3,'rabbit-quest':8,'mary-water':6,'hunter-quest':10,'witch-quest':15,'bones-quest':8,'ritual-purified':12,'lich-quest':20,'empty-grave':8};
export function reward(p,id,kind,amount){if(p.rewards.includes(id))return false;p.rewards.push(id);if(kind==='quest')p.gold=(p.gold||0)+(QUEST_GOLD[id]??5);if(p.level>=MAX_LEVEL){p.xp=0;return true}p.xp+=amount??({quest:40,monster:10,mob:5})[kind];while(p.level<MAX_LEVEL&&p.xp>=xpRequired(p.level)){p.xp-=xpRequired(p.level);p.level++;p.pendingLevels=(p.pendingLevels||0)+1}if(p.level===MAX_LEVEL)p.xp=0;return true}
export function chooseClass(p,id){if(p.classId||p.stage!=='smith'||!CLASSES[id])return false;p.classId=id;p.arrows=id==='bow'?50:0;p.stage='armed';return true}
import {STORY_OBJECTIVES} from './chapter-story.js';
import {RITUAL_OBJECTIVES} from './ritual-quest.js';
export function objective(p){if(Object.hasOwn(STORY_OBJECTIVES,p.stage))return STORY_OBJECTIVES[p.stage];if(Object.hasOwn(RITUAL_OBJECTIVES,p.stage))return RITUAL_OBJECTIVES[p.stage];return {safe:'Найдите безопасное место',offer:'',smith:'Поговорите с кузнецом',armed:'Подойти к Альфреду',wolf:'Победить волка, который бродит у деревни',report:'Вернуться к Альфреду',forest:'Идти в глубь леса',carcasses:'Соберите 3 туши кроликов',delivery:'Вернитесь в деревню',complete:'Поговорите с Мэри',mary_offer:'Поговорите с Мэри',water:'Наберите воду из озера Лонслек',ambush:'Победите волков у озера',water_return:'Вернитесь к Мэри',mary_done:'',hunter_travel:'Отправляйтесь в глубины Темнолесья',hunter_search:'Найдите обезумевшего охотника',hunter_talk:'Поговорите с охотником',hunter_return:'Вернитесь к Альфреду',witch_offer:'',witch:'Победите Ведьму',witch_return:'Вернитесь к Альфреду',witch_done:'Осмотрите письмо ведьмы в инвентаре',bones_talk:'Поговорите с могильщиком Джоном',bones_collect:'Соберите 10 костей скелетов на кладбище',bones_return:'Вернитесь к Джону с костями',bones_done:''}[p.stage]}
export function admit(p){if(p.stage!=='safe')return false;reward(p,'safe','quest');p.stage='offer';return true}
export function kill(p,id,kind,species){const reduced=p.rewards.includes('witch-quest')&&['wolf','hare'].includes(species);reward(p,id,kind,reduced?2:undefined);if(id==='wolf'){p.wolfDead=true;if(p.stage==='wolf')p.stage='report'}}
